-- Canonical service and format definitions captured from the reference catalog.
create table public.service_catalog (id text primary key, definition jsonb not null);
create table public.format_catalog (id text primary key, definition jsonb not null);
alter table public.service_catalog enable row level security;
alter table public.format_catalog enable row level security;
revoke all on public.service_catalog,public.format_catalog from anon,authenticated;
grant select on public.service_catalog,public.format_catalog to authenticated;
create policy service_catalog_read on public.service_catalog for select to authenticated using(true);
create policy format_catalog_read on public.format_catalog for select to authenticated using(true);
alter table public.briefings add constraint briefings_service_type_fkey foreign key(service_type) references public.service_catalog(id);
alter table public.projects add constraint projects_service_type_fkey foreign key(service_type) references public.service_catalog(id);
alter table public.deliverables add constraint deliverables_format_fkey foreign key(format) references public.format_catalog(id);
create function private.validate_briefing_scope() returns trigger language plpgsql security definer set search_path='' as $$
 declare service jsonb; item jsonb; format_spec jsonb; begin
 if new.status='draft' then return new; end if;
 select definition into service from public.service_catalog where id=new.service_type;
 if service is null then raise exception 'Unknown service type'; end if;
 if jsonb_array_length(new.requested_deliverables)=0 then raise exception 'At least one deliverable is required'; end if;
 for item in select value from jsonb_array_elements(new.requested_deliverables) loop
  if length(trim(coalesce(item->>'name','')))=0 or not (service->'formats' ? (item->>'format')) then raise exception 'Select a named deliverable format supported by this service'; end if;
  select definition into format_spec from public.format_catalog where id=item->>'format';
  if format_spec->>'layout'='fixed' and ((item->>'width') is null or (item->>'height') is null or (item->>'width')::integer<=0 or (item->>'height')::integer<=0) then raise exception 'Width and height are required for fixed-size deliverables'; end if;
  if format_spec->>'layout'='fluid' and ((item->>'width') is null or (item->>'width')::integer<=0) then raise exception 'Width is required for fluid deliverables'; end if;
  if coalesce((item->>'quantity')::integer,1) not between 1 and 100 or coalesce(item->>'scope','original') not in ('original','adaptation') then raise exception 'Invalid deliverable quantity or scope'; end if;
 end loop;
 return new;
end $$;
create trigger validate_submitted_briefing_scope before insert or update on public.briefings for each row execute function private.validate_briefing_scope();
revoke execute on function private.validate_briefing_scope() from public,anon,authenticated;
